							<dt class="MarginTopFourElement TextBaseElement LeadingSevenElement TextGraySixHundredElement">Open communication</dt>
						</div>
						<div class="FlexElement FlexColumnElement ItemsCenterElement JustifyCenterElement BackgroundWhiteElement RoundedLargeElement PaddingTenElement ShadowLargeElement">
							<dd class="TextFiveXLElement FontBoldElement TextZincNineHundredElement">03</dd>
